-- Initial PostgreSQL schema. Generated from prisma/schema.prisma; apply with `prisma migrate deploy`.
CREATE TABLE "Tenant" ("id" TEXT PRIMARY KEY, "name" TEXT NOT NULL, "slug" TEXT NOT NULL UNIQUE, "status" TEXT NOT NULL DEFAULT 'ACTIVE', "planTier" TEXT NOT NULL DEFAULT 'STARTER', "website" TEXT, "industry" TEXT, "logoUrl" TEXT, "maxMessagesPerMonth" INTEGER NOT NULL DEFAULT 5000, "maxFlows" INTEGER NOT NULL DEFAULT 5, "maxCampaignLinks" INTEGER NOT NULL DEFAULT 50, "maxStorageMb" INTEGER NOT NULL DEFAULT 100, "customSmtpConfig" TEXT, "aiConfig" TEXT, "widgetSettings" TEXT, "branding" TEXT, "timezone" TEXT NOT NULL DEFAULT 'UTC', "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, "deletedAt" TIMESTAMP(3));
CREATE TABLE "User" ("id" TEXT PRIMARY KEY, "tenantId" TEXT REFERENCES "Tenant"("id") ON DELETE CASCADE, "role" TEXT NOT NULL DEFAULT 'CLIENT_ADMIN', "email" TEXT NOT NULL UNIQUE, "name" TEXT NOT NULL, "passwordHash" TEXT NOT NULL, "status" TEXT NOT NULL DEFAULT 'ACTIVE', "isActive" BOOLEAN NOT NULL DEFAULT true, "mustChangePassword" BOOLEAN NOT NULL DEFAULT false, "lastLoginAt" TIMESTAMP(3), "passwordResetTokenHash" TEXT, "passwordResetExpiresAt" TIMESTAMP(3), "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, "deletedAt" TIMESTAMP(3));
CREATE TABLE "Session" ("id" TEXT PRIMARY KEY, "userId" TEXT NOT NULL REFERENCES "User"("id") ON DELETE CASCADE, "tenantId" TEXT REFERENCES "Tenant"("id") ON DELETE CASCADE, "tokenHash" TEXT NOT NULL UNIQUE, "expiresAt" TIMESTAMP(3) NOT NULL, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "lastSeenAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "ipAddress" TEXT, "userAgent" TEXT, "impersonatedByUserId" TEXT);
CREATE TABLE "TenantUser" ("id" TEXT PRIMARY KEY, "tenantId" TEXT NOT NULL REFERENCES "Tenant"("id") ON DELETE CASCADE, "userId" TEXT NOT NULL REFERENCES "User"("id") ON DELETE CASCADE, "role" TEXT NOT NULL DEFAULT 'CLIENT_ADMIN', "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE("tenantId", "userId"));
CREATE TABLE "Plan" ("id" TEXT PRIMARY KEY, "code" TEXT NOT NULL UNIQUE, "name" TEXT NOT NULL, "isActive" BOOLEAN NOT NULL DEFAULT true, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL);
CREATE TABLE "PlanFeature" ("id" TEXT PRIMARY KEY, "planId" TEXT NOT NULL REFERENCES "Plan"("id") ON DELETE CASCADE, "key" TEXT NOT NULL, "value" INTEGER, "enabled" BOOLEAN NOT NULL DEFAULT true, UNIQUE("planId", "key"));
CREATE TABLE "Subscription" ("id" TEXT PRIMARY KEY, "tenantId" TEXT NOT NULL REFERENCES "Tenant"("id") ON DELETE CASCADE, "planId" TEXT NOT NULL REFERENCES "Plan"("id"), "status" TEXT NOT NULL DEFAULT 'ACTIVE', "startedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "endsAt" TIMESTAMP(3));
CREATE TABLE "Contact" ("id" TEXT PRIMARY KEY, "tenantId" TEXT NOT NULL REFERENCES "Tenant"("id") ON DELETE CASCADE, "name" TEXT, "email" TEXT, "phone" TEXT, "company" TEXT, "source" TEXT, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, "deletedAt" TIMESTAMP(3));
CREATE TABLE "Chatbot" ("id" TEXT PRIMARY KEY, "tenantId" TEXT NOT NULL REFERENCES "Tenant"("id") ON DELETE CASCADE, "name" TEXT NOT NULL, "publicId" TEXT NOT NULL UNIQUE, "description" TEXT, "status" TEXT NOT NULL DEFAULT 'DRAFT', "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, "deletedAt" TIMESTAMP(3));
CREATE TABLE "ChatbotVersion" ("id" TEXT PRIMARY KEY, "chatbotId" TEXT NOT NULL REFERENCES "Chatbot"("id") ON DELETE CASCADE, "versionNumber" INTEGER NOT NULL, "status" TEXT NOT NULL DEFAULT 'DRAFT', "configJson" TEXT NOT NULL DEFAULT '{}', "createdBy" TEXT, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "publishedAt" TIMESTAMP(3), UNIQUE("chatbotId", "versionNumber"));
CREATE TABLE "Flow" ("id" TEXT PRIMARY KEY, "tenantId" TEXT NOT NULL REFERENCES "Tenant"("id") ON DELETE CASCADE, "name" TEXT NOT NULL, "description" TEXT, "version" INTEGER NOT NULL DEFAULT 1, "status" TEXT NOT NULL DEFAULT 'DRAFT', "isDefault" BOOLEAN NOT NULL DEFAULT false, "nodes" TEXT NOT NULL DEFAULT '[]', "edges" TEXT NOT NULL DEFAULT '[]', "publishedNodes" TEXT, "publishedEdges" TEXT, "triggers" TEXT, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, "deletedAt" TIMESTAMP(3));
CREATE TABLE "Campaign" ("id" TEXT PRIMARY KEY, "tenantId" TEXT NOT NULL REFERENCES "Tenant"("id") ON DELETE CASCADE, "name" TEXT NOT NULL, "slug" TEXT NOT NULL, "flowId" TEXT, "metadata" TEXT, "opensCount" INTEGER NOT NULL DEFAULT 0, "conversionsCount" INTEGER NOT NULL DEFAULT 0, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, "deletedAt" TIMESTAMP(3), UNIQUE("tenantId", "slug"));
CREATE TABLE "CampaignContact" ("id" TEXT PRIMARY KEY, "campaignId" TEXT NOT NULL REFERENCES "Campaign"("id") ON DELETE CASCADE, "tenantId" TEXT NOT NULL REFERENCES "Tenant"("id") ON DELETE CASCADE, "contactIdentifier" TEXT NOT NULL, "name" TEXT, "email" TEXT, "phone" TEXT, "customUrlSlug" TEXT NOT NULL UNIQUE, "metadata" TEXT, "opensCount" INTEGER NOT NULL DEFAULT 0, "firstOpenedAt" TIMESTAMP(3), "lastOpenedAt" TIMESTAMP(3), "status" TEXT NOT NULL DEFAULT 'PENDING', "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, "deletedAt" TIMESTAMP(3));
CREATE TABLE "Conversation" ("id" TEXT PRIMARY KEY, "tenantId" TEXT NOT NULL REFERENCES "Tenant"("id") ON DELETE CASCADE, "flowId" TEXT REFERENCES "Flow"("id") ON DELETE SET NULL, "campaignContactId" TEXT REFERENCES "CampaignContact"("id") ON DELETE SET NULL, "visitorId" TEXT NOT NULL, "publicSessionTokenHash" TEXT UNIQUE, "sessionStatus" TEXT NOT NULL DEFAULT 'ACTIVE', "visitorInfo" TEXT, "collectedData" TEXT DEFAULT '{}', "currentNodeId" TEXT, "startedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "lastActiveAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "closedAt" TIMESTAMP(3));
CREATE TABLE "Message" ("id" TEXT PRIMARY KEY, "conversationId" TEXT NOT NULL REFERENCES "Conversation"("id") ON DELETE CASCADE, "senderType" TEXT NOT NULL, "senderName" TEXT, "content" TEXT NOT NULL, "attachments" TEXT, "nodeId" TEXT, "timestamp" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "Lead" ("id" TEXT PRIMARY KEY, "tenantId" TEXT NOT NULL REFERENCES "Tenant"("id") ON DELETE CASCADE, "conversationId" TEXT REFERENCES "Conversation"("id") ON DELETE SET NULL, "name" TEXT, "email" TEXT, "phone" TEXT, "contactInfo" TEXT, "collectedFields" TEXT, "score" INTEGER NOT NULL DEFAULT 0, "status" TEXT NOT NULL DEFAULT 'NEW', "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, "deletedAt" TIMESTAMP(3));
CREATE TABLE "KnowledgeDoc" ("id" TEXT PRIMARY KEY, "tenantId" TEXT NOT NULL REFERENCES "Tenant"("id") ON DELETE CASCADE, "title" TEXT NOT NULL, "category" TEXT, "content" TEXT NOT NULL, "embedding" TEXT, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL);
CREATE TABLE "AnalyticsEvent" ("id" TEXT PRIMARY KEY, "tenantId" TEXT NOT NULL REFERENCES "Tenant"("id") ON DELETE CASCADE, "flowId" TEXT REFERENCES "Flow"("id") ON DELETE SET NULL, "conversationId" TEXT REFERENCES "Conversation"("id") ON DELETE SET NULL, "eventType" TEXT NOT NULL, "nodeId" TEXT, "metadata" TEXT, "timestamp" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "AuditLog" ("id" TEXT PRIMARY KEY, "tenantId" TEXT REFERENCES "Tenant"("id") ON DELETE CASCADE, "userId" TEXT REFERENCES "User"("id") ON DELETE SET NULL, "action" TEXT NOT NULL, "details" TEXT, "ipAddress" TEXT, "timestamp" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "DevEmail" ("id" TEXT PRIMARY KEY, "to" TEXT NOT NULL, "subject" TEXT NOT NULL, "html" TEXT NOT NULL, "text" TEXT NOT NULL, "resetLink" TEXT, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX "User_tenantId_idx" ON "User"("tenantId"); CREATE INDEX "Session_userId_idx" ON "Session"("userId"); CREATE INDEX "Session_tenantId_idx" ON "Session"("tenantId"); CREATE INDEX "Session_expiresAt_idx" ON "Session"("expiresAt"); CREATE INDEX "Flow_tenantId_idx" ON "Flow"("tenantId"); CREATE INDEX "Campaign_tenantId_idx" ON "Campaign"("tenantId"); CREATE INDEX "Conversation_tenantId_idx" ON "Conversation"("tenantId"); CREATE INDEX "Conversation_flowId_idx" ON "Conversation"("flowId"); CREATE INDEX "Message_conversationId_idx" ON "Message"("conversationId"); CREATE INDEX "Lead_tenantId_idx" ON "Lead"("tenantId"); CREATE INDEX "AuditLog_tenantId_idx" ON "AuditLog"("tenantId"); CREATE INDEX "AuditLog_userId_idx" ON "AuditLog"("userId");
